/*
 * One fact per page (facts/<id>.html, generated by tools/build.js).
 * Adds: reading level (simple / detailed), listen (speech synthesis when the
 * device has a voice for the language), save, share card (an image drawn in
 * the browser), a one-question quiz with an explanation, related facts, and
 * "report an error" / "suggest a fact" (email, no personal data).
 */
Medulla.ready(function () {
  "use strict";

  var M = window.Medulla, Store = window.MedullaStore, Tpl = window.MedullaFactTemplate, S = window.MedullaSound;
  var id = document.body.getAttribute("data-fact");
  var art = document.getElementById("fact-article"), side = document.getElementById("fact-side");
  var level = "simple", fact = null, all = [], speaking = false;

  function related(f) {
    var same = all.filter(function (x) { return x.topic === f.topic && x.id !== f.id; });
    var others = all.filter(function (x) { return x.topic !== f.topic && x.character === f.character; });
    return same.concat(others).slice(0, 4);
  }

  function ctx() {
    return { t: M.t, loc: M.localized, base: M.root(), level: level, related: related(fact), saved: Store.isSaved(fact.id) };
  }

  function render() {
    stopSpeaking();
    art.innerHTML = Tpl.article(fact, ctx());
    side.innerHTML = Tpl.side(fact, ctx());
    M.renderIcons(art); M.renderIcons(side);
    M.runRenderers(side);
    document.title = M.localized(fact.title) + " — Medulla";
    var crumbTopic = document.querySelector("[data-crumb-topic]");
    if (crumbTopic) crumbTopic.textContent = M.t("topic." + fact.topic);
  }

  /* --------------------------------------------------------------- listen */

  function voiceFor(langCode) {
    var bcp = (M.langInfo().bcp47 || langCode).toLowerCase();
    var voices = window.speechSynthesis ? speechSynthesis.getVoices() : [];
    return voices.filter(function (v) { return v.lang && v.lang.toLowerCase().indexOf(bcp.slice(0, 2)) === 0; })[0] || null;
  }
  function stopSpeaking() {
    if (window.speechSynthesis && speaking) speechSynthesis.cancel();
    speaking = false;
    var b = art && art.querySelector("[data-listen]");
    if (b) { b.classList.remove("is-speaking"); b.querySelector("span:last-child").textContent = M.t("fact.listen"); }
  }
  function listen(btn) {
    if (speaking) return stopSpeaking();
    if (!("speechSynthesis" in window)) return M.toast({ icon: "headphones", title: M.t("fact.noSpeech") });
    var go = function () {
      var v = voiceFor(M.lang());
      if (!v) return M.toast({ icon: "headphones", title: M.t("fact.noVoice"), text: M.t("fact.noVoiceHint"), ms: 6000 });
      var u = new SpeechSynthesisUtterance(M.localized(fact.title) + ". " + M.localized(fact[level]));
      u.voice = v; u.lang = v.lang; u.rate = 0.95;
      u.onend = u.onerror = function () { stopSpeaking(); };
      speaking = true;
      btn.classList.add("is-speaking");
      btn.querySelector("span:last-child").textContent = M.t("fact.stop");
      speechSynthesis.speak(u);
    };
    if (speechSynthesis.getVoices().length) go();
    else { speechSynthesis.onvoiceschanged = function () { speechSynthesis.onvoiceschanged = null; go(); }; setTimeout(function () { if (!speaking) go(); }, 800); }
  }

  /* ----------------------------------------------------------- share card */

  function wrap(ctx2d, text, maxW) {
    var words = text.split(" "), lines = [], line = "";
    words.forEach(function (w) {
      var test = line ? line + " " + w : w;
      if (ctx2d.measureText(test).width > maxW && line) { lines.push(line); line = w; } else line = test;
    });
    if (line) lines.push(line);
    return lines;
  }
  function loadImg(src) {
    return new Promise(function (res, rej) { var i = new Image(); i.onload = function () { res(i); }; i.onerror = rej; i.src = src; });
  }
  function shareCard() {
    var c = document.createElement("canvas"); c.width = 1200; c.height = 630;
    var g = c.getContext("2d");
    var grd = g.createLinearGradient(0, 0, 1200, 630);
    grd.addColorStop(0, "#FFFFFF"); grd.addColorStop(1, "#E2DEFF");
    g.fillStyle = grd; g.fillRect(0, 0, 1200, 630);
    g.fillStyle = "#6C5CE7"; g.fillRect(0, 590, 1200, 40);
    var who = M.factChar(fact);
    return Promise.all([loadImg(M.root() + "assets/characters/" + who + ".webp"), loadImg(M.root() + "assets/brand/logo-96.webp")]).then(function (imgs) {
      var ch = imgs[0], logo = imgs[1];
      g.fillStyle = "rgba(108,92,231,0.12)"; g.beginPath(); g.arc(1000, 330, 210, 0, Math.PI * 2); g.fill();
      var h = 330, w = h * ch.width / ch.height; g.drawImage(ch, 1000 - w / 2, 520 - h, w, h);
      g.drawImage(logo, 60, 50, 64, 64);
      g.fillStyle = "#0D1128"; g.font = "700 34px Sora, Segoe UI, Arial, sans-serif"; g.fillText("Medulla", 140, 92);
      g.fillStyle = "#6C5CE7"; g.font = "700 20px Segoe UI, Arial, sans-serif"; g.fillText("MIND • LEARN • GROW", 142, 118);
      g.fillStyle = "#5A4AD6"; g.font = "700 24px Segoe UI, Arial, sans-serif"; g.fillText(M.t("topic." + fact.topic).toUpperCase(), 60, 200);
      g.fillStyle = "#0D1128"; g.font = "700 52px Sora, Segoe UI, Arial, sans-serif";
      var y = 262;
      wrap(g, M.localized(fact.title), 720).slice(0, 3).forEach(function (l) { g.fillText(l, 60, y); y += 62; });
      g.fillStyle = "#3D4157"; g.font = "400 26px Segoe UI, Arial, sans-serif";
      wrap(g, M.localized(fact.simple), 720).slice(0, 3).forEach(function (l) { g.fillText(l, 60, y + 10); y += 36; });
      g.fillStyle = "#FFFFFF"; g.font = "600 20px Segoe UI, Arial, sans-serif";
      g.fillText(M.t("common.source") + " " + M.publisher(fact) + " · " + M.t("common.pendingReview"), 60, 617);
      return c;
    });
  }
  function onShare() {
    shareCard().then(function (c) {
      c.toBlob(function (blob) {
        var file = new File([blob], "medulla-" + fact.id + ".png", { type: "image/png" });
        var url = (window.MEDULLA_CONFIG.domain ? window.MEDULLA_CONFIG.domain + "/facts/" + fact.id + ".html" : location.href.split("#")[0]);
        if (navigator.canShare && navigator.canShare({ files: [file] })) {
          navigator.share({ files: [file], title: M.localized(fact.title), text: M.localized(fact.title) + " — Medulla", url: url }).catch(function () { /* cancelled */ });
          return;
        }
        var slot = side.querySelector("[data-share-slot]");
        var href = URL.createObjectURL(blob);
        slot.hidden = false;
        slot.innerHTML = '<h2 class="h3" style="margin:0 0 10px">' + M.esc(M.t("fact.shareCard")) + "</h2>" +
          '<img class="share-preview" src="' + href + '" width="1200" height="630" alt="' + M.esc(M.t("fact.shareAlt", { title: M.localized(fact.title) })) + '">' +
          '<div class="btn-row" style="margin-top:10px"><a class="btn btn-primary btn-sm press" href="' + href + '" download="medulla-' + fact.id + '.png">' + M.icon("download") + "<span>" + M.esc(M.t("fact.download")) + "</span></a></div>";
        slot.scrollIntoView({ block: "nearest", behavior: M.reducedMotion() ? "auto" : "smooth" });
      }, "image/png");
    });
  }

  /* ----------------------------------------------------------------- quiz */

  function answer(btn) {
    var box = btn.closest("[data-quiz]");
    if (box.classList.contains("is-answered")) return;
    box.classList.add("is-answered");
    var pick = +btn.getAttribute("data-opt"), ok = pick === fact.quiz.answer;
    box.querySelectorAll(".quiz-option").forEach(function (b) {
      b.disabled = true;
      var oi = +b.getAttribute("data-opt");
      if (oi === fact.quiz.answer) b.classList.add("is-right");
      else if (b === btn) b.classList.add("is-wrong");
    });
    box.querySelector(".quiz-why-slot").innerHTML = '<div class="quiz-react">' + M.poseImg(M.factChar(fact), ok ? "correct" : "tryagain", "pose", true) +
      '<p class="quiz-why">' + M.icon(ok ? "check" : "info") + "<span><strong>" +
      M.esc(M.t(ok ? "quiz.right" : "quiz.notQuite")) + "</strong> " + M.esc(M.localized(fact.quiz.why)) + "</span></p></div>";
    if (ok) S.correct(); else S.wrong();
    Store.record("quiz", { correct: ok, fact: fact.id });
  }

  /* --------------------------------------------------------------- events */

  art.addEventListener("click", function (e) {
    var lv = e.target.closest("[data-level]");
    if (lv) { level = lv.getAttribute("data-level"); render(); art.querySelector('[data-level="' + level + '"]').focus(); return; }
    if (e.target.closest("[data-listen]")) return listen(e.target.closest("[data-listen]"));
    var sv = e.target.closest("[data-save]");
    if (sv) {
      var on = Store.toggleSave(fact.id);
      M.toast({ icon: "bookmark", title: M.t(on ? "fact.savedToast" : "fact.unsavedToast"), ms: 1800 });
      render(); art.querySelector("[data-save]").focus();
      return;
    }
    if (e.target.closest("[data-share-card]")) return onShare();
    var opt = e.target.closest(".quiz-option");
    if (opt) answer(opt);
  });
  window.addEventListener("pagehide", stopSpeaking);
  M.onLangChange(render);

  M.loadFacts().then(function (facts) {
    all = facts;
    fact = facts.filter(function (f) { return f.id === id; })[0];
    if (!fact) return;
    render();
    M.readFact(fact);
  });
});
